const app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>JSON.stringify(x,null,2);
const params=new URLSearchParams(location.search), state=params.get('state')||'catalog';
let selected, catalog;
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,data:await r.json()};}
function step(n){document.querySelectorAll('#progress a').forEach((a,i)=>{a.classList.toggle('active',i===n-1);if(i===n-1)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});}
function heading(n,title,text){step(n);return `<p class="step">Step ${n} of 3</p><h1>${title}</h1><p class="intro">${text}</p>`;}
function error(e){app.innerHTML=`<h1>We could not load this page.</h1><p>${esc(e.message)}</p><p>Check the API connection, then reload the page.</p><a href="?state=catalog">Return to the library</a>`;}
function catalogView(){app.innerHTML=heading(1,'What do you want verified?','Choose a result from the library, or paste a request. We look for an existing proof or checker that matches it.')+`<div class="tabs"><strong>Choose from the library</strong><a href="#request">Paste a request</a></div><form id="choose">${catalog.entries.map((e,i)=>`<label class="entry-option"><input type="radio" name="entry" value="${esc(e.id)}" ${i===0?'checked':''}><span><strong>${esc(e.title)}</strong><small>${esc(e.kind)} / ${e.replay_status==='recorded'?'Recorded only; not re-run by fvapi':'Replay available'}</small><p>${esc(e.claim)}</p><a href="?state=entry&amp;id=${encodeURIComponent(e.id)}">Read this entry</a></span></label>`).join('')}<div class="actions"><button>Look up this result</button><span class="hint">${catalog.entries.length} results in the library</span></div></form><details id="request"><summary>Paste a hash, statement or result ID instead</summary><form id="query"><label class="field">Request type<select id="key"><option value="spec_id">Result ID</option><option value="artifact_sha256">Artifact SHA-256</option><option value="statement">Statement text</option></select></label><label class="field">Your request<textarea id="value" required placeholder="Paste the exact statement, hash or ID"></textarea></label><button>Look up</button></form></details>`;document.querySelector('a[href="#request"]').onclick=()=>{document.querySelector('#request').open=true;};document.querySelector('#choose').onsubmit=e=>{e.preventDefault();lookup({spec_id:new FormData(e.target).get('entry')}).catch(error);};document.querySelector('#query').onsubmit=e=>{e.preventDefault();lookup({[document.querySelector('#key').value]:document.querySelector('#value').value}).catch(error);};}
async function lookup(query){const r=await api('lookup',query);step(2);if(r.status===404){app.innerHTML=heading(2,'No matching result yet.','A miss means that the library did not find a matching entry. It does not mean that your statement is false.')+`<div class="notice warn"><strong>Logged as demand</strong><p>Your request helps identify gaps in the library. It is not sent to an agent for a proof.</p></div><h2>Your request</h2><pre>${esc(pretty(r.data.query||query))}</pre><details><summary>Response details</summary><pre>${esc(pretty(r.data))}</pre></details><div class="actions"><a class="button" href="?state=catalog">Try another request</a><a href="?state=demand">See demand log</a></div>`;return;}if(r.status!==200)throw Error(r.data.detail||'Lookup failed');selected=r.data.entry|| (await api('catalog/'+r.data.entry_id)).data;app.innerHTML=heading(2,'We found a matching result.','A match is the start, not the final check. Read what the proof says, then confirm that it is the result you need.')+`<div class="notice"><strong>Match found</strong><p>Matched on ${esc(r.data.matched_on)}. Answer ${esc(r.data.answer_id)}.</p></div><h2>${esc(selected.title)}</h2><p>${esc(selected.claim)}</p><h3>Read the formal statement</h3>${selected.statements.map(s=>`<pre>${esc(s.text)}</pre>`).join('')}<div class="actions"><button id="continue">Continue to the evidence</button><a href="?state=catalog">Choose a different request</a></div>`;document.querySelector('#continue').onclick=()=>entryView(selected);}
function entryView(e){selected=e;app.innerHTML=heading(3,'Check it yourself.','fvapi supplies the files and the instructions. Your own replay is what lets you check the result without trusting the service.')+`<h2>${esc(e.title)}</h2><p>${esc(e.claim)}</p><div class="notice ${e.replay.status==='recorded'?'warn':''}"><strong>${e.replay.status==='recorded'?'Recorded only — not re-run by fvapi':'Real replay available'}</strong><p>${e.replay.status==='recorded'?'This transcript comes from an earlier run. fvapi has not re-run this proof.':''} ${esc(e.replay.note)}</p></div><h2>Read the statement first</h2><p class="hint">Make sure this says what you need. A valid proof of a different statement does not verify your request.</p>${e.statements.map(s=>`<h3>${esc(s.name)}</h3><p class="mini">${esc(s.file)}:${s.line}</p><pre>${esc(s.text)}</pre>`).join('')}<section class="section"><h2>Get the proof files</h2><p>The bundle includes the statement, proof files and a manifest. Compare each file with its SHA-256 value before replay.</p><a class="button secondary" href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download bundle</a><ul class="files">${e.closure.map(f=>`<li><strong>${esc(f.path)}</strong> <span class="mini">${esc(f.bytes)} bytes</span><code>SHA-256 ${esc(f.sha256)}</code></li>`).join('')}</ul></section><section class="section"><h2>Replay on your machine</h2><p>Use ${esc(e.toolchain)} with ${esc(e.requires.join(', '))}. Run this command inside the extracted bundle.</p><pre id="command">${esc(e.replay.command)}</pre><button class="secondary" id="copy">Copy replay command</button><p><strong>Expected axioms:</strong> ${esc(e.replay.expect_axioms.join(', ')||'none')}</p>${e.replay.transcript?`<details><summary>Earlier transcript (not a new replay)</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}</section><section class="section"><h2>Run a check on your input</h2><p>${e.check?'Edit the JSON below, then run the checker. A server result is a lead; replay the same check locally.':'This entry has no runnable input checker. You can replay the proof files instead.'}</p>${e.check?`<label class="field" for="input">Input JSON</label><textarea id="input" spellcheck="false">${esc(pretty(e.check.example_input))}</textarea><button id="run">Run check</button> <button class="link" id="reset">Restore example</button>`:`<button class="secondary" id="run">Try an input check</button>`}<div id="result" aria-live="polite"></div></section><section class="section"><h2>Source and licence</h2><dl><dt>Source</dt><dd>${esc(e.source.repo)}</dd><dt>Commit</dt><dd>${esc(e.source.commit)}</dd><dt>Files</dt><dd>${esc(e.source.paths.join(', '))}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)}: ${esc(t.spdx)}; ${esc(t.source)}`).join('<br>'):'No third-party notices listed in this entry.'}</dd></dl></section><div class="actions"><a href="?state=catalog">Start another request</a></div>`;document.querySelector('#copy').onclick=async ev=>{try{await navigator.clipboard.writeText(e.replay.command);ev.target.textContent='Command copied';}catch{ev.target.textContent='Select and copy the command above';}};document.querySelector('#run').onclick=()=>runCheck().catch(showCheckError);if(e.check)document.querySelector('#reset').onclick=()=>{document.querySelector('#input').value=pretty(e.check.example_input);};}
function showCheckError(e){document.querySelector('#result').innerHTML=`<div class="notice warn"><strong>The check could not run.</strong><p>${esc(e.message)} Correct the input JSON and try again.</p></div>`;}
async function runCheck(){let input={};if(selected.check)input=JSON.parse(document.querySelector('#input').value);const r=await api('checks/'+encodeURIComponent(selected.id),input);if(r.status!==200&&r.status!==409)throw Error(r.data.detail||`HTTP ${r.status}`);const no=r.status===409;const reject=r.data.verdict==='reject';document.querySelector('#result').innerHTML=`<div class="notice ${no||reject?'warn':''}"><strong>${no?'No runnable checker for this entry':reject?'Input rejected':'Input accepted'}</strong><p>${no?'Use the proof replay above, or choose a checker from the library.':reject?'The input does not satisfy this checker. Review the output and correct the weights before trying again.':'The server checker accepted this input. Re-run it locally before you rely on the result.'}</p>${no?'<p>HTTP 409 / no_checker</p>':`<p>Exit code ${esc(r.data.exit_code)}; ${esc(r.data.elapsed_ms)} ms; ran on ${esc(r.data.ran_on)}.</p>`}</div><details open><summary>${no?'Response':'Checker output and local recheck'}</summary><pre>${esc(pretty(r.data))}</pre></details>`;}
async function logs(){step(0);const [d,a]=await Promise.all([api('demand'),api('answers')]);app.innerHTML=`<p class="step">Operator view</p><h1>What people ask for.</h1><p class="intro">Misses reveal gaps in the library. Answers record the results that the service returned.</p><a href="?state=catalog">Return to the guided flow</a><h2>Demand by request</h2>${d.data.by_key.length?`<table><thead><tr><th>Request key</th><th>Count</th></tr></thead><tbody>${d.data.by_key.map(x=>`<tr><td><code>${esc(x.key)}</code></td><td>${esc(x.count)}</td></tr>`).join('')}</tbody></table>`:'<p>No demand yet. Try a lookup to start.</p>'}<h2>Recent misses</h2>${d.data.misses.map(x=>`<details open><summary>${esc(x.miss_id)} / ${esc(x.at)}</summary><pre>${esc(pretty(x.query))}</pre></details>`).join('')||'<p>No misses logged.</p>'}<h2>Answer log</h2><pre>${esc(pretty(a.data))}</pre>`;}
(async()=>{catalog=(await api('catalog')).data;if(state==='catalog'||state==='mobile')return catalogView();if(state==='demand'||state==='answers')return logs();if(state.startsWith('lookup-'))return lookup({spec_id:state==='lookup-hit'?'vf.contrast-2x2':'missing.example'});const id=params.get('id')||(state==='recorded'||state==='check-409'?'fva.glm-iround':'vf.contrast-2x2');const r=await api('catalog/'+encodeURIComponent(id));if(r.status!==200)throw Error(r.data.detail);entryView(r.data);if(state.startsWith('check-')){if(state==='check-reject'){const input=structuredClone(selected.check.example_input);input.rows[0].weights[0]+=1;document.querySelector('#input').value=pretty(input);}await runCheck();document.querySelector('#result').scrollIntoView();}})().then(()=>document.body.dataset.ready='true').catch(error);
